import torch


def gen_inputs(ctx, device):
    x1_shape = ctx["x1__shape"]
    x2_shape = ctx["x2__shape"]
    grad_shape = ctx["grad__shape"]
    dtype = getattr(torch, ctx["x1__dtype"])
    x1 = torch.randn(x1_shape, dtype=dtype, device=device)
    x2 = torch.randn(x2_shape, dtype=dtype, device=device)
    grad = torch.randn(grad_shape, dtype=dtype, device=device)
    cdist = torch.cdist(x1, x2, p=2.0)
    return {"x1": x1, "x2": x2, "grad": grad, "cdist": cdist}


def run(grad, x1, x2, p, cdist):
    return torch.ops.aten._cdist_backward(grad, x1, x2, p, cdist)
